                        foregroundColor: inCart
                            ? Colors.red.shade700
                            : Colors.white,
                        padding: const EdgeInsets.symmetric(
                          horizontal: 18,
                          vertical: 14,
                        ),
                      ),
                      onPressed: () {
                        context
                            .read<CartProvider>()
                            .toggleItem(product);
                      },
                      child: Text(
                        inCart ? 'Remove' : 'Add +',
                      ),
                    ),
